import{templates}from"./templates.js";const routes={"/":templates.home,"/projetos":templates.projetos,"/cadastro":templates.cadastro},titulos={"/":"Início","/projetos":"Projetos","/cadastro":"Cadastro"};function getPath(){return location.hash.slice(1)||"/"}function render(e=!1){const t=document.getElementById("app"),o=getPath(),n=routes[o]??templates.notFound;t.replaceChildren(),t.insertAdjacentHTML("beforeend",n()),window.scrollTo(0,0),document.title=`${titulos[o]??"Página não encontrada"} - Mãos Solidárias`,e&&t.focus(),document.getElementById("menu-principal")?.classList.remove("aberto"),document.getElementById("menu-toggle")?.setAttribute("aria-expanded","false")}export function initRouter(){window.addEventListener("hashchange",()=>render(!0)),render()}export function rerenderizarRotaAtual(){render()}